          <CardContent>
            {!rows.length ? (
              <Muted>{t("nhcx_nothing_quoted_add")}</Muted>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>{t("nhcx_kind")}</TableHead>
