                  </TableHeader>
                  <TableBody>
                    {rows.map(({ line, tiers, amount }) => (
                      <TableRow key={line.id}>
                        <TableCell>
                          <Chip tone={LINE_KIND[line.kind]?.tone ?? "neutral"}>
