const IMPLANT_FLAGS = [
  "ImplantApplicable",
  "MultipleImplantsAllowed",
  "MaximumImplantsAllowed",
];

function Section({
  value,
  title,
  children,
}: {
  value: string;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <AccordionItem value={value}>
      <AccordionTrigger>{title}</AccordionTrigger>
      <AccordionContent>{children}</AccordionContent>
    </AccordionItem>
